<?php
if(!defined('ABSPATH'))exit;
add_action('init',function(){if(get_option('bhc_catalog_quality_audit_v256'))return;$products=wc_get_products(['limit'=>-1,'status'=>['draft','publish','private','pending']]);$summary=['checked'=>0,'missing_source'=>0,'missing_specs'=>0,'missing_description'=>0,'missing_image'=>0,'image_not_4k'=>0,'candidate_image'=>0,'verified_reference'=>0,'ready'=>0,'by_category'=>[]];foreach($products as $p){$id=$p->get_id();$issues=[];$source=(string)$p->get_meta('_bhc_source_url');$spec=(string)$p->get_meta('_bhc_structured_specs');$desc=trim(wp_strip_all_tags((string)$p->get_description()));$image=(int)$p->get_image_id();$edge=(int)$p->get_meta('_bhc_image_long_edge');$status=(string)$p->get_meta('_bhc_image_status');if(!$source){$issues[]='missing_exact_source';$summary['missing_source']++;}if(!$spec){$issues[]='missing_structured_specs';$summary['missing_specs']++;}if(mb_strlen($desc)<400){$issues[]='short_product_description';$summary['missing_description']++;}if(!$image){$issues[]='missing_featured_image';$summary['missing_image']++;}if($image&&$edge<4096){$issues[]='image_long_edge_below_4096';$summary['image_not_4k']++;}if($status==='generated_4k_transparent_candidate'){$issues[]='image_needs_reference_match';$summary['candidate_image']++;}if($p->get_meta('_bhc_verification_status')==='verified_reference')$summary['verified_reference']++;if($p->get_meta('_bhc_catalog_quality_state')==='ready')$summary['ready']++;$terms=wp_get_post_terms($id,'product_cat',['fields'=>'names']);foreach($terms as $cat){if(!isset($summary['by_category'][$cat]))$summary['by_category'][$cat]=['count'=>0,'issues'=>0];$summary['by_category'][$cat]['count']++;if($issues)$summary['by_category'][$cat]['issues']++;}update_post_meta($id,'_bhc_quality_issues',wp_json_encode(array_values(array_unique($issues)),JSON_UNESCAPED_UNICODE));update_post_meta($id,'_bhc_quality_audit_checked_at','2026-11-20');$summary['checked']++;}update_option('bhc_catalog_quality_audit_v256',['summary'=>$summary,'at'=>current_time('mysql'),'policy'=>'Products remain hidden/draft/outofstock until exact source, structured specs, complete description and image-reference QA pass.'],false);},256);
